<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-btn v-if="can('product.manage')" block class="mb-3" prepend-icon="mdi-plus" @click="dialog=true">제품 등록</v-btn><v-expansion-panels><v-expansion-panel v-for="p in products" :key="p.id"><v-expansion-panel-title><div><div class="font-weight-bold">{{ p.name }}</div><div class="text-caption">{{ p.store?.name }} · {{ p.category?.name }} · {{ p.is_active?'사용':'중지' }}</div></div></v-expansion-panel-title><v-expansion-panel-text><div class="text-body-2 mb-2">현재가 {{ latestPrice(p).toLocaleString() }}원</div><v-btn v-if="can('product.manage')" size="small" variant="outlined" @click="toggle(p,setError)">사용 상태 변경</v-btn><v-divider class="my-3"/><div class="font-weight-bold mb-2">레시피</div><div v-for="r in p.recipes" :key="r.id" class="mb-3"><div>{{ r.name }}</div><div class="text-caption">재료: {{ r.ingredients?.map(i=>`${i.name} ${i.quantity}${i.unit}`).join(', ')||'없음' }}</div><ol class="text-caption pl-5"><li v-for="s in r.steps" :key="s.id">{{ s.description }}</li></ol></div><v-btn v-if="can('recipe.manage')" size="small" @click="openRecipe(p)">레시피 추가</v-btn></v-expansion-panel-text></v-expansion-panel></v-expansion-panels><v-dialog v-model="dialog" max-width="400"><v-card title="제품 등록"><v-card-text><v-select v-model="form.store_id" :items="stores" item-title="name" item-value="id" label="점포" variant="outlined"/><v-select v-model="form.product_category_id" :items="categories.filter(c=>c.store_id===form.store_id)" item-title="name" item-value="id" label="카테고리" variant="outlined"/><v-text-field v-model="form.name" label="제품명" variant="outlined"/><v-select v-model="form.production_department" :items="departments" label="생산 부서" variant="outlined"/><v-select v-model="form.management_department" :items="departments" label="관리 부서" variant="outlined"/><v-number-input v-model="form.price" label="판매가" :min="0" variant="outlined"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">취소</v-btn><v-btn @click="save(setError)">저장</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="recipeDialog" max-width="400"><v-card title="레시피 추가"><v-card-text><v-text-field v-model="recipe.name" label="레시피명" variant="outlined"/><v-textarea v-model="recipe.description" label="설명" variant="outlined"/><v-textarea v-model="recipe.ingredientsText" label="재료 (한 줄에 이름,수량,단위)" variant="outlined"/><v-textarea v-model="recipe.stepsText" label="공정 (한 줄에 한 단계)" variant="outlined"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="recipeDialog=false">취소</v-btn><v-btn @click="saveRecipe(setError)">저장</v-btn></v-card-actions></v-card></v-dialog></template></AppShell></template>
<script setup>
import{computed,onMounted,ref}from'vue';import AppShell from'../../components/layout/AppShell.vue';const pageTitle='제품 관리';const products=ref([]),categories=ref([]),dialog=ref(false),recipeDialog=ref(false),selected=ref(null);const form=ref({store_id:null,product_category_id:null,name:'',production_department:'kitchen',management_department:'kitchen',price:0});const recipe=ref({name:'',description:'',ingredientsText:'강력분,100,g\n버터,20,g',stepsText:'재료를 계량한다.\n반죽하고 발효한다.'});const departments=[{title:'주방',value:'kitchen'},{title:'홀',value:'hall'}];const stores=computed(()=>[...new Map(categories.value.map(c=>[c.store_id,{id:c.store_id,name:products.value.find(p=>p.store_id===c.store_id)?.store?.name??`점포 ${c.store_id}`}])).values()]);function latestPrice(p){return p.prices?.[0]?.price??0;}async function load(){const d=(await window.axios.get('/tillwhite/api/products')).data;products.value=d.products;categories.value=d.categories;}async function save(err){try{await window.axios.post('/tillwhite/api/products',form.value);dialog.value=false;await load();}catch(e){err(e.response?.data?.message??'제품 저장 실패');}}async function toggle(p,err){try{await window.axios.put(`/tillwhite/api/products/${p.id}/toggle`);await load();}catch(e){err(e.response?.data?.message??'변경 실패');}}function openRecipe(p){selected.value=p;recipeDialog.value=true;}async function saveRecipe(err){try{const ingredients=recipe.value.ingredientsText.split('\n').filter(Boolean).map(x=>{const [name,quantity,unit]=x.split(',');return{name,quantity:Number(quantity),unit};});const steps=recipe.value.stepsText.split('\n').filter(Boolean).map(description=>({description}));await window.axios.post(`/tillwhite/api/products/${selected.value.id}/recipes`,{name:recipe.value.name,description:recipe.value.description,ingredients,steps});recipeDialog.value=false;await load();}catch(e){err(e.response?.data?.message??'레시피 저장 실패');}}onMounted(load);
</script>
